args.source:
import type { Plugin } from "../../kernel/types";

const plugin: Plugin = {
  id: "result-panel",
  name: "Result Panel",
  version: "1.0.0",
  onLoad(ctx) {
    ctx.register({
      kind: "api",
      api: {
        mount: "panel",
        version: "1.0.0",
        description: "Returns a simple panel JSON payload.",
        permissions: {
          capabilities: [{ kind: "api", name: "panel" }]
        },
        sideEffect: "read",
        router: async (req: any, res: any) => {
          const payload = { title: "Panel", html: "<p>value=29</p>" };
          if (res && typeof res.status === "function") {
            res.status(200).json(payload);
            return;
          }
          return payload;
        }
      }
    });
  }
};

export default plugin;

